-- Datos de prueba v3 | reconstrucción de datos | solo test
-- Reconstruye los datos de prueba y reemplaza cuentas, turnos y consultas existentes.
-- Conserva anuncios, posiciones y referencias de imágenes. Hacer respaldo y pausar servicios antes.
-- Requiere el esquema de cartelera de las migraciones 002 y 003.
-- Las cuentas de demo activadas usan una contraseña común (ver la guía). No ejecuta llamadas externas.
BEGIN;
SET LOCAL search_path = pg_catalog, public, pg_temp;
SET LOCAL TIME ZONE 'America/Montevideo';
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '5min';

DO $destino$
DECLARE esperado text[] := ARRAY['anuncio', 'anuncio_archivo_pendiente_borrado', 'atencion', 'aviso_llegada', 'consulta', 'consultorio', 'cuenta', 'dispositivo_push', 'enlace_cuenta', 'envio_notificacion', 'especialidad', 'imagen_anuncio', 'medico_especialidad', 'notificacion', 'numero', 'numero_semanal', 'pase', 'persona', 'sesion', 'turno', 'turno_evento', 'turno_semanal'];
DECLARE real text[];
BEGIN
 IF current_database() <> 'test' THEN
   RAISE EXCEPTION 'Destino incorrecto: %, se esperaba test', current_database();
 END IF;
 SELECT array_agg(c.relname::text ORDER BY c.relname::text COLLATE "C") INTO real
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relkind IN ('r','p','f');
 IF real IS DISTINCT FROM esperado THEN RAISE EXCEPTION 'Cambió el inventario de tablas de test: %', real; END IF;
 IF EXISTS (SELECT FROM pg_trigger g JOIN pg_class c ON c.oid=g.tgrelid
            WHERE c.relnamespace='public'::regnamespace AND NOT g.tgisinternal AND g.tgenabled<>'D') THEN
   RAISE EXCEPTION 'Hay triggers de aplicación activos; revisar sus efectos antes de cargar';
 END IF;
END $destino$;

LOCK TABLE public.anuncio,
  public.anuncio_archivo_pendiente_borrado,
  public.atencion,
  public.aviso_llegada,
  public.consulta,
  public.consultorio,
  public.cuenta,
  public.dispositivo_push,
  public.enlace_cuenta,
  public.envio_notificacion,
  public.especialidad,
  public.imagen_anuncio,
  public.medico_especialidad,
  public.notificacion,
  public.numero,
  public.numero_semanal,
  public.pase,
  public.persona,
  public.sesion,
  public.turno,
  public.turno_evento,
  public.turno_semanal
  IN ACCESS EXCLUSIVE MODE;

SELECT set_config('demo.desplazamiento', (CURRENT_DATE-DATE '2026-10-27')::text, true);
-- La cuenta nueva queda por encima de las cuentas y del contador existentes; nunca
-- se reinicia esa secuencia al valor bajo de la referencia.
SELECT set_config('demo.base_cuenta', greatest(
  1000000::bigint, (SELECT coalesce(max(id_cuenta),0) FROM public.cuenta),
  (SELECT last_value FROM public.cuenta_id_cuenta_seq)
)::text, true);

CREATE TEMP TABLE demo_anuncios_antes ON COMMIT DROP AS
SELECT id_anuncio, to_jsonb(a) - ARRAY['id_administrador','vigente_desde','vigente_hasta'] AS contenido,
       vigente_desde AS inicio
FROM public.anuncio a;
CREATE TEMP TABLE demo_imagenes_antes ON COMMIT DROP AS SELECT * FROM public.imagen_anuncio;

DO $cartelera$
BEGIN
 IF EXISTS (SELECT FROM public.anuncio) AND CURRENT_DATE >= DATE '2028-01-01' THEN
   RAISE EXCEPTION 'El fin de vigencia solicitado ya pasó';
 END IF;
 IF EXISTS (SELECT FROM public.anuncio_archivo_pendiente_borrado b
            JOIN public.imagen_anuncio i USING (referencia_archivo)) THEN
   RAISE EXCEPTION 'La cola de borrado apunta a imágenes conservadas; mantener pausado su proceso y revisar';
 END IF;
END $cartelera$;

-- Solo tablas operativas; RESTRICT impide truncar dependencias desconocidas.
TRUNCATE TABLE
  public.anuncio_archivo_pendiente_borrado,
  public.atencion,
  public.aviso_llegada,
  public.consulta,
  public.consultorio,
  public.dispositivo_push,
  public.enlace_cuenta,
  public.envio_notificacion,
  public.especialidad,
  public.medico_especialidad,
  public.notificacion,
  public.numero,
  public.numero_semanal,
  public.pase,
  public.sesion,
  public.turno,
  public.turno_evento,
  public.turno_semanal
  RESTART IDENTITY RESTRICT;

-- Se inserta la cuenta final con una persona provisional para evitar colisiones
-- de CI. La cuenta queda deshabilitada y sin credenciales durante la operación.
INSERT INTO public.persona (ci,nombre,apellido,fecha_nacimiento)
VALUES ('D3PUENTE','Demo','Provisional',DATE '1980-01-01');
INSERT INTO public.cuenta (id_cuenta,ci,rol,correo,telefono_1,habilitada)
OVERRIDING SYSTEM VALUE
VALUES ((current_setting('demo.base_cuenta')::bigint + 1),'D3PUENTE','ADMINISTRADOR','demo-v3-puente@example.invalid','000000000',false);
UPDATE public.anuncio
SET id_administrador = (current_setting('demo.base_cuenta')::bigint + 1),
    vigente_desde = least(vigente_desde, transaction_timestamp()),
    vigente_hasta = (TIMESTAMP '2028-01-01 00:00:00' AT TIME ZONE 'America/Montevideo');
-- LEAST en PostgreSQL ignora NULL; devolver el inicio abierto cuando ya lo estaba.
UPDATE public.anuncio a SET vigente_desde=NULL
FROM pg_temp.demo_anuncios_antes b
WHERE b.id_anuncio=a.id_anuncio AND b.inicio IS NULL;

UPDATE public.cuenta
SET ultimo_inactivador=NULL, ultima_inactivacion_en=NULL,
    ultimo_reactivador=NULL, ultima_reactivacion_en=NULL
WHERE id_cuenta <> (current_setting('demo.base_cuenta')::bigint + 1)
  AND (ultimo_inactivador IS NOT NULL OR ultimo_reactivador IS NOT NULL);
DELETE FROM public.cuenta WHERE id_cuenta <> (current_setting('demo.base_cuenta')::bigint + 1);
DELETE FROM public.persona WHERE ci <> 'D3PUENTE';

