-- ALTER SEQUENCE RESTART se revierte junto con la transacción ante una falla.
DO $secuencias$
DECLARE r record; siguiente bigint; secuencia regclass;
BEGIN
 FOR r IN SELECT table_name,column_name FROM information_schema.columns
    WHERE table_schema='public' AND is_identity='YES'
      AND table_name NOT IN ('anuncio','imagen_anuncio','anuncio_archivo_pendiente_borrado')
 LOOP
   secuencia := pg_get_serial_sequence(format('public.%I',r.table_name),r.column_name)::regclass;
   EXECUTE format('SELECT coalesce(max(%I),0)+1 FROM public.%I',r.column_name,r.table_name) INTO siguiente;
   EXECUTE format('ALTER SEQUENCE %s RESTART WITH %s',secuencia,siguiente);
 END LOOP;
END $secuencias$;
-- 1. Cantidad de persona: 50
DO $v$ BEGIN
 IF (SELECT count(*) <> 50 AS error FROM public.persona) THEN RAISE EXCEPTION 'Verificación fallida: Cantidad de persona: 50'; END IF;
END $v$;

-- 2. Cantidad de cuenta: 50
DO $v$ BEGIN
 IF (SELECT count(*) <> 50 AS error FROM public.cuenta) THEN RAISE EXCEPTION 'Verificación fallida: Cantidad de cuenta: 50'; END IF;
END $v$;

