-- 14. Cantidad de consulta: 267
DO $v$ BEGIN
 IF (SELECT count(*) <> 267 AS error FROM public.consulta) THEN RAISE EXCEPTION 'Verificación fallida: Cantidad de consulta: 267'; END IF;
